import {phantom,addNoise,filter,metrics,hardware,emptyState,validateState} from './core.js';
const $=(q)=>document.querySelector(q), $$=(q)=>[...document.querySelectorAll(q)];
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',folder:'<path d="M3 6h7l2 3h9v12H3z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',flask:'<path d="M8 3h8m-6 0v7L4 20h16l-6-10V3M7 16h10"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 4v16M4 12h16"/>'};
const icon=(key,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]||icons.book}</svg>`;
const chapters=[['basics','基础概念','认识像素与噪声'],['papers','英文论文阅读','读懂方法与证据'],['algorithms','算法对比','建立可复现基线'],['ideas','创新点设计','把想法变成假设'],['hardware','硬件实现','从像素流到 FPGA'],['experiments','实验评估','用数据验证结论']];
const names={home:'学习首页',lab:'自主实验',guide:'工作台使用教程',knowledge:'基础知识入手',overview:'研究概览',library:'研究资料库',...Object.fromEntries(chapters.map(c=>[c[0],c[1]]))};
let state=emptyState(), storageOK=true, loadError='';
try{const raw=localStorage.getItem('ir-lab-v1');if(raw)state=validateState(JSON.parse(raw));}catch(e){storageOK=false;loadError='浏览器保存不可用，或已有记录无法读取。请先导出备份；本次更改仅暂存内存。';}
let page='overview',timer=null,windowIndex=0,libraryCategory='全部',libraryQuery='',selectedPaper=null;
let demo={type:'salt',level:10,seed:42,method:'median',threshold:30,reference:phantom(),source:'合成灰度测试图',w:96,h:96};
let latest=null;
const noiseNames={salt:'椒盐噪声',gaussian:'高斯噪声',stripe:'列条纹噪声'}, methodNames={median:'3×3 中值滤波',mean:'3×3 均值滤波',switch:'开关中值（实验方法）'};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('toast-visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4500);}
function persist(){if(!storageOK){toast('已暂存内存，请导出备份以保存');return;}try{localStorage.setItem('ir-lab-v1',JSON.stringify(state));}catch(e){storageOK=false;toast('浏览器空间不足或禁止保存，请立即导出备份');}renderSidebar();}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAll(){download('红外去噪研究备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));toast('备份已导出，包含论文、实验、笔记与进度');}
const uid=()=>crypto.randomUUID();
function renderSidebar() {
  const sections=[['home','学习首页','home'],['knowledge','基础知识入手','book'],['guide','工作台使用教程','arrow'],['lab','自主实验','flask']];
  const link=([id,title,mark])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(mark)}${title}</a>`;
  $('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark">${'<i></i>'.repeat(9)}</div><div><strong>红外去噪研究台</strong><small>INFRARED RESEARCH LAB</small></div></div><nav aria-label="学习导航">${sections.map(link).join('')}</nav><details class="extra-nav" ${sections.some(s=>s[0]===page)?'':'open'}><summary>研究工具与资料</summary><nav aria-label="研究工具">${[['overview','研究概览','home'],...chapters,['library','研究资料库','folder']].map(link).join('')}</nav></details><div class="side-bottom"><p>${storageOK?'记录保存在此浏览器。':'记录仅暂存在内存。'}换设备前可导出备份。</p></div>`;
}
function pageHead(eyebrow,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function panel(title,body,extra='',className=''){return `<section class="panel ${className}"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`;}
function chapterHead(id,sub){const i=chapters.findIndex(c=>c[0]===id);return pageHead(`CHAPTER 0${i+1} / RESEARCH PATH`,names[id],sub,`<button data-action="chapter" data-id="${id}">${state.chapters.includes(id)?'✓ 已完成本章':'标记本章已完成'}</button>`);}
function path(){return `<div class="path">${chapters.map((c,i)=>`<a href="#${c[0]}" class="${i===0&&!state.chapters.includes(c[0])?'current':''}"><small>0${i+1} ${state.chapters.includes(c[0])?'✓':'→'}</small><strong>${c[1]}</strong><span class="state">${state.chapters.includes(c[0])?'已完成':c[2]}</span></a>`).join('')}</div>`;}
function defaultTasks(){return[{id:'first-basics',title:'理解 3×3 中值滤波',detail:'基础概念 · 观察窗口，找到第 5 个值',link:'basics',done:state.chapters.includes('basics')},{id:'first-paper',title:'精读并记录一篇英文论文',detail:'英文论文阅读 · 先提取问题和方法',link:'papers',done:state.papers.length>0},{id:'first-exp',title:'完成第一组基线对比',detail:'算法对比 · 固定噪声密度与随机种子',link:'algorithms',done:state.experiments.length>0}];}
function taskMarkup(tasks){return tasks.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" aria-label="完成：${esc(t.title)}" data-task="${esc(t.id)}" ${t.done||state.checks.includes(t.id)?'checked':''}><div><strong>${esc(t.title)}</strong><p>${esc(t.detail||'自定义研究任务')}</p>${t.link?`<a class="small muted" href="#${t.link}">前往完成 →</a>`:''}</div>${!t.link?`<button class="text-button small" data-action="delete-task" data-id="${esc(t.id)}" aria-label="删除任务">×</button>`:''}</div>`).join('');}
function progressPanel(){return panel('研究进度',`<div class="panel-body"><div class="row spread"><span class="small muted">章节学习进度</span><span class="mono small">${state.chapters.length} / 6</span></div><div class="progress-track"><i style="width:${state.chapters.length/6*100}%"></i></div><div class="number-row"><div><strong>${String(state.papers.length).padStart(2,'0')}</strong><small>论文笔记</small></div><div><strong>${String(state.experiments.length).padStart(2,'0')}</strong><small>实验记录</small></div><div><strong>${String(state.notes.filter(n=>n.category==='待验证想法').length).padStart(2,'0')}</strong><small>待验证想法</small></div></div></div>`,'<span class="section-label">PROGRESS</span>');}
function overview(){return pageHead('RESEARCH WORKSPACE / 研究工作台','把每一个想法，变成可验证的结果。','聚焦制冷型红外图像去噪，从读懂一篇论文，到跑通一个 FPGA 实验。',`<button class="primary row" data-action="new-note">${icon('plus',15)} 新建研究笔记</button>`)+`<div class="chips" style="margin-top:-10px;margin-bottom:24px"><span class="chip">制冷型红外探测器</span><span class="chip">纯数字处理</span><span class="chip">8 位灰度</span><span class="chip filled">3×3 中值滤波</span></div>`+path()+`<div class="two-col"><div class="stack">${demoPanel()}${panel('从一个像素，理解一次去噪',`<div class="panel-body"><p class="muted">窗口取出 9 个灰度值，排序后选第 5 个，替换窗口中心像素。</p><div class="flow"><button data-go="basics">输入像素</button><span>→</span><button data-go="basics">3×3 窗口</button><span>→</span><button data-go="basics">排序取中值</button><span>→</span><button data-go="hardware">输出像素</button></div><div class="row spread"><span class="small muted">从可视化开始，再连接行缓存与流水线。</span><a href="#basics" class="small">打开滑动演示 ↗</a></div></div>`,'<span class="section-label">HOW IT WORKS</span>')}${panel('研究入口',`<div class="panel-body" style="padding-top:0;padding-bottom:0"><a class="mini-link" href="#papers"><span class="mini-icon">${icon('book')}</span><div><h3>英文论文阅读工作区</h3><p>摘要拆解、术语释义、方法复现与改进点</p></div><span class="arrow">↗</span></a><a class="mini-link" href="#hardware"><span class="mini-icon">${icon('chip')}</span><div><h3>FPGA 实现路线</h3><p>行缓存 → 窗口生成 → 中值运算 → 时序验证</p></div><span class="arrow">↗</span></a></div>`)}</div><div class="stack">${panel('下一步任务',`<div class="panel-body" style="padding-top:4px;padding-bottom:8px">${taskMarkup([...defaultTasks(),...state.tasks].slice(0,5))}</div><div class="panel-body" style="padding-top:4px"><button class="text-button small" data-action="new-task">＋ 添加研究任务</button></div>`,'<span class="section-label">NEXT STEPS</span>')}${progressPanel()}${reviewPanel()}<div class="panel"><div class="panel-body"><div class="eyebrow">RESEARCH NOTE / 研究提醒</div><h3>先建立基线，再讨论创新。</h3><p class="muted" style="margin-top:12px">固定输入、噪声种子和边界策略，才能判断结果变化来自算法，还是实验条件。</p><a href="#ideas" class="small" style="display:inline-block;margin-top:16px">设计可验证的假设 →</a></div></div></div></div>`;}
function demoPanel(){return panel('去噪交互实验',`<div class="experiment-toolbar"><label class="field inline"><span>噪声类型</span><select id="noiseType">${Object.entries(noiseNames).map(([k,v])=>`<option value="${k}" ${demo.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field inline"><span id="noiseLabel">${demo.type==='salt'?'噪声密度':'噪声幅度'} <b id="noiseValue">${demo.level}${demo.type==='salt'?'%':''}</b></span><input id="noiseLevel" type="range" min="0" max="${demo.type==='salt'?90:60}" value="${demo.level}" aria-label="噪声强度"></label><label class="field inline"><span>去噪方法</span><select id="filterMethod">${Object.entries(methodNames).map(([k,v])=>`<option value="${k}" ${demo.method===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="image-grid"><figure class="image-tile"><canvas id="cleanCanvas" width="96" height="96" aria-label="参考灰度图"></canvas><figcaption><strong>01 / 参考图</strong><span>8-bit</span></figcaption></figure><figure class="image-tile"><canvas id="noisyCanvas" width="96" height="96" aria-label="添加噪声的图像"></canvas><figcaption><strong>02 / 含噪图</strong><span id="inputNoise">${demo.level}%</span></figcaption></figure><figure class="image-tile"><canvas id="outCanvas" width="96" height="96" aria-label="滤波结果"></canvas><figcaption><strong>03 / 去噪结果</strong><span id="outputName">中值滤波</span></figcaption></figure></div><div class="legend-note" id="demoNote"></div><div class="metrics"><div class="metric"><small>去噪 PSNR</small><strong id="psnrValue">—</strong><p>越高越接近参考图</p></div><div class="metric"><small>分块 SSIM</small><strong id="ssimValue">—</strong><p>结构相似性 · 理想值 1</p></div><div class="metric"><small>窗口 / 像素范围</small><strong>3×3 <em>/ 0–255</em></strong><p>边界复制 · 输出取整</p></div></div><details class="panel-body" style="border-top:1px solid var(--line)"><summary class="small muted">实验设置与保存</summary><div class="split-fields" style="margin-top:16px"><label class="field"><span>随机种子（同一种子复现同一噪声）</span><input id="noiseSeed" type="number" min="0" max="4294967295" step="1" value="${demo.seed}"></label><label class="field"><span>开关中值阈值（灰度差）</span><input id="switchThreshold" type="number" min="0" max="255" step="1" value="${demo.threshold}"></label><label class="field full"><span>可选：载入参考图（视为干净图，缩放为 96×96 灰度；≤10 MB）</span><input id="imageUpload" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="controls"><button class="primary" data-action="save-demo">保存这一组实验</button><button data-action="reset-image">恢复合成图</button><button data-action="download-image">导出去噪图</button></div><p class="small muted gap">本页 SSIM 使用不重叠 8×8 方块、均匀权重、总体方差，K₁=0.01、K₂=0.03、L=255；它是教学口径，与原论文高斯加权 SSIM 不可直接混用。合成图不代表真实红外探测器数据。</p></details>`,'<span class="live"><span class="status-dot"></span>可交互演示</span>');}
function drawCanvas(id,data){const c=$(id);if(!c)return;const ctx=c.getContext('2d'),img=ctx.createImageData(96,96);data.forEach((v,i)=>{img.data[i*4]=img.data[i*4+1]=img.data[i*4+2]=v;img.data[i*4+3]=255;});ctx.putImageData(img,0,0);}
function updateDemo(){const noisy=addNoise(demo.reference,demo.type,demo.level,demo.seed);const output=filter(noisy,96,96,demo.method,demo.threshold);const m=metrics(demo.reference,output,96,96);latest={noisy,output,m};drawCanvas('#cleanCanvas',demo.reference);drawCanvas('#noisyCanvas',noisy);drawCanvas('#outCanvas',output);if($('#psnrValue')){$('#psnrValue').innerHTML=`${Number.isFinite(m.psnr)?m.psnr.toFixed(2):'∞'} <em>dB</em>`;$('#ssimValue').textContent=m.ssim.toFixed(4);$('#noiseValue').textContent=demo.level+(demo.type==='salt'?'%':'');$('#inputNoise').textContent=noiseNames[demo.type];$('#outputName').textContent=demo.method==='switch'?'开关中值':methodNames[demo.method].replace('3×3 ','');$('#demoNote').textContent=`${demo.source} · 96×96 · 随机种子 ${demo.seed}。${demo.type==='salt'?'以设定概率把像素替换为 0 或 255，实际受污染比例可能略有差异。':demo.type==='gaussian'?'幅度为高斯噪声标准差，叠加后截断到 0–255。':'固定列偏置演示，幅度为灰度峰值；不是对探测器噪声的完整建模。'}`;}if($('#compareBody'))renderComparison();if($('#labComparison'))updateLab();}
function bindDemo(){if(!$('#noiseType'))return;$('#noiseType').onchange=e=>{demo.type=e.target.value;demo.level=Math.min(demo.level,demo.type==='salt'?90:60);render();};$('#noiseLevel').oninput=e=>{demo.level=Number(e.target.value);updateDemo();};$('#filterMethod').onchange=e=>{demo.method=e.target.value;updateDemo();};$('#noiseSeed').onchange=e=>{if(!e.target.checkValidity()||e.target.value===''){toast('随机种子需为 0–4294967295 的整数');e.target.value=demo.seed;return;}demo.seed=Number(e.target.value);updateDemo();};$('#switchThreshold').onchange=e=>{if(!e.target.checkValidity()||e.target.value===''){toast('阈值需为 0–255 的整数');e.target.value=demo.threshold;return;}demo.threshold=Number(e.target.value);updateDemo();};$('#imageUpload').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){toast('图片超过 10 MB，请选择较小图片');return;}let url=URL.createObjectURL(f);try{const img=new Image();img.src=url;await img.decode();const c=document.createElement('canvas');c.width=c.height=96;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,96,96);ctx.drawImage(img,0,0,96,96);let data=ctx.getImageData(0,0,96,96).data;demo.reference=Uint8Array.from({length:9216},(_,i)=>Math.round(.299*data[i*4]+.587*data[i*4+1]+.114*data[i*4+2]));demo.source='用户参考图：'+f.name;updateDemo();toast('已载入，原图作为本次实验的参考图');}catch(err){toast('无法读取图片，请选择有效的 PNG、JPEG 或 WebP');}finally{URL.revokeObjectURL(url);}};updateDemo();}
function basics(){return chapterHead('basics','从像素、噪声和窗口开始。先理解每一步，再动手写代码。')+`<div class="cards"><div class="concept"><span class="eyebrow">01 / 像素</span><div class="big">0 → 255</div><h3>8 位灰度图像</h3><p>每个像素用 8 位无符号数表示，共 256 级。0 为黑，255 为白。真实探测器原始位深可能更高：转为 8 位前需固定映射和截断策略。</p></div><div class="concept"><span class="eyebrow">02 / 噪声</span><div class="big">0 · 255</div><h3>椒盐噪声模型</h3><p>本实验随机把像素设为黑或白。真实图像中的坏点、读出噪声、条纹需分别验证；制冷并不意味着所有噪声都是椒盐噪声。</p></div><div class="concept"><span class="eyebrow">03 / 算法</span><div class="big">9 → 1</div><h3>3×3 中值滤波</h3><p>取中心周围 9 个值并排序，用第 5 个替换中心。它能抵抗孤立极端值，也可能抹掉小目标和细线，需要共同评估。</p></div></div><div class="gap">${panel('3×3 窗口滑动演示',`<div class="panel-body"><div class="matrix-layout"><div><div id="matrix" class="matrix" aria-label="7×7 像素矩阵"></div><div class="controls"><button data-action="window-prev" id="windowPrev" aria-label="上一个窗口">← 上一步</button><button class="primary" data-action="window-play" id="windowPlay">自动播放</button><button data-action="window-next" id="windowNext">下一步 →</button><button data-action="window-reset">重置</button></div></div><div><span class="eyebrow" id="windowPosition"></span><h3 style="margin-top:12px">把 9 个值从小到大排列</h3><div id="sortValues" class="sort-values"></div><div class="formula" id="windowResult"></div><p class="muted">深色格为窗口中心，浅色框为当前 3×3 窗口。每一步向右移动一个像素，到行末后进入下一行。</p><p class="muted gap">此演示只展示内部 25 个有效窗口。完整图像实验采用边界复制：越界位置使用最近的边缘像素。</p></div></div></div>`,'<span class="stat-tag">7×7 示例矩阵</span>')}</div><div class="gap">${panel('图像去噪流程',`<div class="panel-body"><p class="muted">点击节点查看该步骤的输入、输出和需要注意的问题。</p><div class="flow" id="pipeline">${['获取数字图像','统一到 8 位','建立噪声模型','3×3 滤波','质量与硬件评估'].map((v,i)=>`<button data-action="flow" data-index="${i}" class="${i===0?'selected':''}">${v}</button>${i<4?'<span>→</span>':''}`).join('')}</div><div class="callout" id="flowDetail"></div></div>`)}</div><div class="gap">${panel('本章自检',`<div class="panel-body">${checklist(['concept-1','concept-2','concept-3'],['能解释为什么 8 位无符号像素最大值是 255','能手算一组 9 个数的中值，并区别于平均值','能说明真实红外噪声与人工椒盐噪声模型的区别'])}</div>`)}</div>`;}
const matrixValues=Array.from({length:49},(_,i)=>[0,11,19,24,40].includes(i)?(i%2?0:255):60+(i%7)*9+Math.floor(i/7)*4);
function updateWindow(){if(!$('#matrix'))return;const x=windowIndex%5+1,y=Math.floor(windowIndex/5)+1;let values=[];$('#matrix').innerHTML=matrixValues.map((v,i)=>{const ix=i%7,iy=Math.floor(i/7),inside=Math.abs(ix-x)<=1&&Math.abs(iy-y)<=1;if(inside)values.push(v);return `<div class="cell ${inside?'in-window':''} ${ix===x&&iy===y?'center':''}">${v}</div>`;}).join('');values.sort((a,b)=>a-b);$('#sortValues').innerHTML=values.map((v,i)=>`<span class="${i===4?'median':''}">${v}</span>`).join('');$('#windowPosition').textContent=`WINDOW ${String(windowIndex+1).padStart(2,'0')} / 25 · 中心坐标 (${x}, ${y}) · 从 0 计数`;$('#windowResult').innerHTML=`原中心值 ${matrixValues[y*7+x]} → 中值 <strong>${values[4]}</strong><br>y(x, y) = sort(window)[4]`;$('#windowPrev').disabled=windowIndex===0;$('#windowNext').disabled=windowIndex===24;}
const flowDetails=['输入：探测器读出后的数字图像。保存原始文件、尺寸、位深和采集条件；本研究从数字像素开始，不涉及模拟读出电路设计。','固定从原始位深到 0–255 的映射。对所有方法使用同一映射，避免自动拉伸改变实验条件。保留原始高位深数据以便检查量化损失。','有参考图时可添加可重复的噪声；真实数据没有干净参考时，不能直接把含噪图当真值报告 PSNR。记录噪声类型、密度、随机种子与假设。','按行扫描输入，用两行缓存和移位寄存器得到 3×3 邻域。选择边界处理策略，然后计算中值、均值或待验证的改进方法。','软件记录 PSNR、SSIM 和边缘/小目标表现；硬件记录 LUT、FF、BRAM、DSP、WNS、时钟和吞吐率。每个数值要有输入条件与结果来源。'];
function checklist(ids,labels){return `<div class="checklist">${ids.map((id,i)=>`<label><input type="checkbox" data-check="${id}" ${state.checks.includes(id)?'checked':''}>${labels[i]}</label>`).join('')}</div>`;}
const paperFields=[['title','论文题目','text',true],['url','原文链接 / DOI','text'],['authors','作者','text'],['abstract','英文摘要','textarea'],['keywords','关键词','text'],['method','核心方法（输入、判断、输出）','textarea'],['dataset','数据集、来源与噪声设置','textarea'],['metrics','评价指标与比较基线','textarea'],['improvements','局限和可改进点','textarea'],['paragraph','待精读的英文段落','textarea'],['translation','逐句理解 / 中文转述','textarea'],['terms','术语及在本文中的含义','textarea'],['questions','研究问题（作者解决了什么、证据是什么）','textarea'],['idea','创新思路与待验证假设','textarea'],['next','下一步阅读或复现任务','textarea'],['reviewDate','计划复习日期','date']];
const glossary=[['salt-and-pepper noise','椒盐噪声','像素被替换为极端黑白值的脉冲噪声模型。'],['impulse noise','脉冲噪声','少量像素发生突变；可能是固定极值，也可能是随机灰度。'],['median filter','中值滤波','将邻域排序，选择中间值的非线性滤波。'],['switching filter','开关滤波','先判断像素是否可疑，再决定保留或滤波。'],['line buffer','行缓存','保存前面行的像素，以便组成二维邻域。'],['pipeline','流水线','将计算拆成寄存器分隔的多级，多个像素可同时处于不同阶段。'],['latency','延迟','某个像素从输入到输出所经历的时间或周期数。'],['throughput','吞吐率','单位时间完成的像素数，不等于延迟的倒数。'],['PSNR','峰值信噪比','由与干净参考图的均方误差计算的指标，单位 dB。'],['SSIM','结构相似性','比较亮度、对比度和结构；必须说明窗口与实现口径。'],['non-uniformity','非均匀性','相同输入下，不同探测单元可能产生不同响应。'],['ablation study','消融实验','移除或替换一个模块，验证它是否贡献性能。']];
function papers(){const selected=state.papers.find(p=>p.id===selectedPaper);return chapterHead('papers','带着问题阅读：先找研究问题，再找方法，最后核对实验是否支持结论。')+`<div class="two-col"><div class="stack">${panel('我的论文笔记',`<div class="panel-body">${state.papers.length?state.papers.map(p=>paperCard(p)).join(''):'<div class="empty"><h3>从第一篇论文开始</h3>不必一次读懂全文。先记录标题、摘要和三个关键词。<br><button class="primary gap" data-action="new-paper">＋ 录入英文论文</button></div>'}</div>`,`<button class="small" data-action="new-paper">＋ 新论文</button>`)}${selected?paperDetail(selected):panel('一篇论文，分四次读',`<div class="panel-body guide">${[['看问题','读标题、摘要和结论，写一句话：作者想解决什么？'],['看方法','画出输入 → 噪声判断 → 滤波 → 输出，标出需要排序或乘法的步骤。'],['看证据','检查数据来源、噪声密度、基线、指标与运行条件是否一致。'],['看机会','把局限改写成可验证假设：改变什么、预期改善什么、可能损失什么？']].map((v,i)=>`<div class="guide-item"><span class="step-num">0${i+1}</span><div><h3>${v[0]}</h3><p>${v[1]}</p></div></div>`).join('')}</div>`)}${panel('精读练习：先抓住条件与动作',`<div class="panel-body"><span class="chip">原创教学示例 · 非论文引文</span><div class="reading-block" lang="en">If a pixel is identified as an impulse, its value is replaced by the median of its neighborhood. Otherwise, the original value is retained.</div><p><strong>条件：</strong>像素被判定为脉冲噪声。<br><strong>动作：</strong>用邻域中值替换。<br><strong>另一分支：</strong>保留原值。</p><div class="callout">需要追问：如何判定脉冲？真正的黑白目标会被误判吗？噪声密度升高时，邻域中值还可靠吗？</div><button data-action="new-paper">把自己的段落放进精读笔记</button></div>`)}</div><div class="stack">${panel('随手查术语',`<div class="panel-body"><input class="search" id="termSearch" placeholder="搜索英文或中文术语" aria-label="搜索术语"><div id="terms"></div></div>`)}${panel('阅读起点与资料',`<div class="panel-body"><a href="https://www.ece.uwaterloo.ca/~z70wang/publications/ssim.html" target="_blank" rel="noopener">Image Quality Assessment: From Error Visibility to Structural Similarity ↗</a><p class="muted gap">Wang 等，2004。用于理解评价指标；并非针对制冷型红外图像的去噪论文。</p><button class="small gap" data-action="sample-paper">用这篇论文建立待阅读卡</button><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><a href="https://www.mathworks.com/help/images/noise-removal.html" target="_blank" rel="noopener">MathWorks：噪声去除与中值/均值对比 ↗</a><p class="muted gap">作为算法学习资料。竞赛研究仍需要补充真实红外数据与相关论文。</p></div>`)}</div></div>`;}
function paperCard(p){return `<article class="record-card"><div class="row spread"><span class="chip">${esc(p.status||'待阅读')}</span><span class="small muted">${p.reviewDate?'复习 '+esc(p.reviewDate):'未设复习日期'}</span></div><h3 style="margin-top:12px">${esc(p.title)}</h3><p>${esc((p.abstract||p.method||'尚未填写摘要，点击精读继续整理。').slice(0,180))}</p><div class="actions"><button data-action="read-paper" data-id="${p.id}">打开精读</button><button data-action="edit-paper" data-id="${p.id}">编辑笔记</button><button data-action="review-paper" data-id="${p.id}">复习完成</button><button class="danger" data-action="delete" data-kind="papers" data-id="${p.id}">删除</button></div></article>`;}
function paperDetail(p){let safeURL='';try{const u=new URL(p.url);if(['http:','https:'].includes(u.protocol))safeURL=u.href;}catch(e){}return panel('精读工作区',`<div class="panel-body"><h3>${esc(p.title)}</h3>${safeURL?`<p class="gap"><a href="${esc(safeURL)}" target="_blank" rel="noopener">打开原文 ↗</a></p>`:''}<dl>${paperFields.filter(([k])=>!['title','url','reviewDate'].includes(k)).map(([k,label])=>`<dt>${label}</dt><dd>${esc(p[k]||'尚未记录。点击编辑笔记补充。')}</dd>`).join('')}</dl><button class="primary" data-action="edit-paper" data-id="${p.id}">继续编辑精读笔记</button><p class="muted gap">研究问题提取提示：把“方法有效”拆成噪声模型、输入条件、比较对象和证据四项。此工作区提供阅读引导，所有理解与结论由你核对原文后记录。</p></div>`);}
function renderTerms(query=''){if(!$('#terms'))return;const list=glossary.filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase()));$('#terms').innerHTML=list.length?list.map(x=>`<details style="border-bottom:1px solid var(--line);padding:14px 0"><summary class="small">${esc(x[0])} <span class="muted">/ ${x[1]}</span></summary><p class="muted" style="margin-top:10px">${x[2]}</p></details>`).join(''):'<p class="muted gap">未找到该术语，可将它加入论文的术语笔记。</p>';}
function algorithms(){return chapterHead('algorithms','在同一输入下比较效果，记录条件，再判断改进是否成立。')+`<div class="stack">${demoPanel()}${panel('同条件算法对比',`<div class="table-wrap"><table><thead><tr><th>方法</th><th>PSNR / dB</th><th>分块 SSIM</th><th>运算结构</th><th>硬件资源 / 延迟</th></tr></thead><tbody id="compareBody"></tbody></table></div><div class="panel-body"><p class="muted">上表图像指标由当前输入实时计算。资源占用和时序与器件、结构、约束、综合设置有关，必须实测；浏览器执行时间不能代替 FPGA 延迟。</p></div>`,'<span class="chip">同一噪声输入 · 同一边界策略</span>')}${panel('三种方法到底有什么不同？',`<div class="panel-body"><div class="cards"><div class="concept"><h3>中值滤波</h3><div class="formula">y = sort(p₀…p₈)[4]</div><p>对孤立极端值较稳健。排序可用比较交换网络，具体级数由实现决定。窄线、小目标和密集噪声需单独检查。</p></div><div class="concept"><h3>均值滤波</h3><div class="formula">y = round(Σ pᵢ / 9)</div><p>9 项和最大 2295，至少需要 12 位无符号数。平均会摊开极端值并模糊边缘。定点除法与舍入要和软件一致。</p></div><div class="concept"><h3>可扩展：开关中值</h3><div class="formula">extreme &amp; |p−m|&gt;T<br>? m : p</div><p>仅中心是 0/255 且与中值差超过 T 时替换。它是待验证的教学改进，不能默认是创新或一定优于基线；需考察真实黑白目标误判。</p></div></div><div class="callout">扩展研究：改变噪声检测条件、引入局部差异阈值，或调整排序架构。每次只改变一个因素，并将预期收益和可能代价写进创新点卡片。</div><button data-action="new-idea">记录一个改进假设</button></div>`)}</div>`;}
function renderComparison(){if(!latest)return;$('#compareBody').innerHTML=Object.keys(methodNames).map(k=>{const m=metrics(demo.reference,filter(latest.noisy,96,96,k,demo.threshold),96,96);return `<tr><td>${methodNames[k]}</td><td class="mono">${Number.isFinite(m.psnr)?m.psnr.toFixed(2):'∞'}</td><td class="mono">${m.ssim.toFixed(4)}</td><td>${k==='median'?'比较 / 选择':k==='mean'?'加法 / 定点除法':'比较 / 条件选择'}</td><td class="muted">待综合与时序实测</td></tr>`;}).join('');}
function ideas(){return chapterHead('ideas','把“可能更好”写成明确假设，再设计能推翻它的实验。')+`<div class="two-col"><div class="stack">${panel('我的待验证想法',`<div class="panel-body">${state.notes.filter(n=>n.category==='待验证想法').map(noteCard).join('')||'<div class="empty"><h3>先写下一个能被验证的问题</h3>例如：只替换可疑像素，是否能减少低噪声图像的细节损失？</div>'}</div>`,`<button class="primary small" data-action="new-idea">＋ 新假设</button>`)}${panel('从想法到证据',`<div class="panel-body guide">${[['观察限制','在噪声密度 30% 的输入下，3×3 中值还有多少残留坏点？先保存基线。'],['提出机制','如果先判断像素是否受污染，可能减少正常像素被修改，但检测本身也会误判。'],['定义对照','同样的图像、种子、位深和边界策略，对比中值、均值、你的方法。'],['设计反例','加入真正的 0/255 像素、窄线、小目标、均匀区域与高噪声，检查方法何时失效。'],['核查新颖性','查找同类方法，确认区别。指标更好不自动意味着学术创新；还需说明机制与适用范围。']].map((v,i)=>`<div class="guide-item"><span class="step-num">0${i+1}</span><div><h3>${v[0]}</h3><p>${v[1]}</p></div></div>`).join('')}</div>`)}</div><div class="stack">${panel('一张好的假设卡',`<div class="panel-body"><p>建议在正文中填写：</p><div class="formula">问题：在哪些输入下失效？<br>改变：具体修改哪一步？<br>假设：为什么可能改善？<br>基线：与谁公平比较？<br>指标：改善多少才算有用？<br>代价：资源、延迟、细节损失？<br>反例：怎样证明假设不成立？</div><button data-action="idea-template">使用这份模板</button></div>`)}${panel('硬件可实现性检查',`<div class="panel-body">${checklist(['idea-1','idea-2','idea-3','idea-4'],['每个判断能否用有限位宽的加法、比较或查表表示？','是否需要更大窗口、更多行缓存或多个时钟周期？','阈值如何配置，是否需要训练或现场标定？','算法收益是否足以抵偿资源、功耗或吞吐率代价？'])}</div>`)}</div></div>`;}
const hardwareSteps=[['明确像素接口','约定 clk、rst、pixel_in[7:0]、in_valid，以及行/帧边界信号。只在 in_valid 有效时接收一个像素；若有背压，需同时满足 ready。'],['形成 3×3 窗口','用两行缓存保留前两行，三条移位链保存各行相邻像素。先用 7×7 小图，打印 9 个窗口值，与手算结果逐项核对。'],['实现中值核心','把 9 个无符号数排序，取第 5 个。先实现功能正确版本，再选择比较网络和流水线。一个可综合写法并不自动满足频率要求。'],['对齐 valid 与像素位置','数据经过多少级寄存器，valid、坐标和边界标志就延迟多少级。复位清除有效状态；每行开始时处理跨行污染。'],['仿真逐像素对照','用同一输入和边界策略产生软件参考结果，逐像素比较。检查全黑、全白、极值、随机图、行末与输入停顿。'],['综合、布局布线与上板','选择真实器件和目标时钟，查看 LUT/FF/BRAM/DSP 和 WNS。上板后核对输入输出数量、首个有效像素与帧边界，再保存报告。']];
function hardwarePage(){return chapterHead('hardware','先跑通像素与有效信号，再优化频率和资源。不需要一开始就熟悉所有开发工具。')+`<div class="two-col"><div class="stack">${panel('FPGA 分步实施路线',`<div class="panel-body guide">${hardwareSteps.map((s,i)=>`<div class="guide-item"><span class="step-num">0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></div>`).join('')}</div>`)}${panel('流水线波形示意',`<div class="panel-body"><p class="muted">示例假设：窗口已经准备好，核心延迟为 3 拍；无背压，每拍可接收一个窗口。空拍随 valid 一起传递。</p>${waveform()}<div class="callout">这张波形仅解释“延迟 3 拍”。整帧首次输出还需等待窗口填充。具体周期数由输入握手、行缓存读延迟、边界策略和流水线共同决定。</div></div>`)}${panel('Verilog 学习笔记：先写接口约定',`<div class="panel-body"><p class="muted">下列是接口草图，尚未包含可运行的滤波核心。先理解每个信号，再在你的 FPGA 工程中实现。</p><pre>input  wire       clk;
input  wire       rst;
input  wire       in_valid;
input  wire [7:0] pixel_in;
output wire       out_valid;
output wire [7:0] pixel_out;
// 行/帧边界及 ready 按实际接口补充
// valid 必须与对应的数据一起延迟</pre><button data-action="verilog-note">建立 Verilog 实现笔记</button></div>`)}</div><div class="stack">${panel('吞吐率与缓存估算',`<div class="panel-body"><div class="split-fields"><label class="field"><span>时钟频率 / MHz</span><input id="hwClock" type="number" value="100" min="0.01" step="any"></label><label class="field"><span>输入间隔 II / 拍</span><input id="hwII" type="number" value="1" min="1" step="1"></label><label class="field"><span>核心延迟 / 拍</span><input id="hwCycles" type="number" value="9" min="0" step="1"></label><label class="field"><span>图像宽度 / 像素</span><input id="hwWidth" type="number" value="640" min="3" max="16384" step="1"></label><label class="field"><span>图像高度 / 像素</span><input id="hwHeight" type="number" value="512" min="3" max="16384" step="1"></label></div><div class="formula" id="hwResult"></div><p class="muted">理论吞吐率 = f / II。上限帧率忽略消隐、输入停顿与窗口填充。两行缓存容量仅含像素位，不含控制和移位寄存器，也不等于实际 BRAM 块数。</p></div>`,'<span class="chip">理论估算</span>')}${panel('常见问题排查',`<div class="panel-body">${[['图像横向错位','检查行首的移位寄存器清理、行长度计数与边界复制位置。'],['结果晚一拍或早一拍','追踪数据与 valid 的每一级寄存器；检查同步 RAM 读延迟。'],['白点滤波后变黑','检查是否误用有符号比较，或位宽不足发生截断。'],['仿真正确，上板异常','检查复位、跨时钟域、输入时序与实际引脚约束，再核对时序报告。'],['无法达到目标频率','查看关键路径，考虑拆分比较链并加入流水线，同时重新对齐 valid。']].map(x=>`<details style="padding:14px 0;border-bottom:1px solid var(--line)"><summary class="small">${x[0]}</summary><p class="muted" style="margin-top:12px">${x[1]}</p></details>`).join('')}<button class="small gap" data-action="hardware-note">记录排查过程</button></div>`)}</div></div>`;}
function waveform(){let rows=[['clk','clock'],['in_valid','1110111000'],['窗口输入','ABC·DEF···'],['out_valid','0001110111'],['像素输出','···abc·def']];return `<svg class="wave" viewBox="0 0 660 220" role="img" aria-label="三拍流水线波形，输入 A 在三个周期后输出 a"><rect x="0" y="0" width="660" height="220" fill="#fafcf7"/>${Array.from({length:11},(_,i)=>`<line x1="${120+i*50}" x2="${120+i*50}" y1="20" y2="205" stroke="#e3e9db" stroke-dasharray="3 3"/>`).join('')}${rows.map(([name,data],r)=>{const y=36+r*36;let body='';if(data==='clock')body=`<path d="M120 ${y+10} ${Array.from({length:10},(_,i)=>`H${120+i*50} V${y-8} H${145+i*50} V${y+10} H${170+i*50}`).join(' ')}" fill="none" stroke="#667b54" stroke-width="1.5"/>`;else if(name.includes('valid'))body=`<path d="M120 ${y+8} ${[...data].map((v,i)=>`H${120+i*50} V${v==='1'?y-8:y+8} H${170+i*50}`).join(' ')}" fill="none" stroke="#667b54" stroke-width="1.5"/>`;else body=[...data].map((v,i)=>`<text x="${140+i*50}" y="${y+4}" fill="#475c35" font-size="12" font-family="monospace">${v}</text>`).join('');return `<text x="12" y="${y+4}" fill="#6c795f" font-size="12" font-family="monospace">${name}</text>${body}`;}).join('')}</svg>`;}
function updateHardware(){try{const els=['#hwClock','#hwII','#hwCycles','#hwWidth','#hwHeight'].map($);if(els.some(e=>e.value===''||!e.checkValidity()))throw Error('请填写有效的正数；周期、间隔和尺寸须为整数。');const m=hardware(...els.map(e=>Number(e.value)));$('#hwResult').innerHTML=`理论吞吐率 <strong>${m.throughput.toFixed(2)} Mpix/s</strong><br>核心延迟 ${m.latency.toFixed(3)} μs<br>满流量帧率上限 ${m.frameRate.toFixed(2)} fps<br>两行像素缓存 ${m.lineBits.toLocaleString()} bit`; }catch(e){$('#hwResult').textContent=e.message;}}
const expFields=[['title','实验名称','text',true],['algorithm','算法 / 版本','text',true],['dataset','数据集与参考图来源','text'],['params','参数（位深、窗口、边界、噪声密度、种子等）','textarea'],['psnr','PSNR / dB（可填 Infinity；无参考图留空）','text'],['ssim','SSIM（注明实现口径）','number'],['ssimMethod','SSIM 计算口径 / 工具版本','text'],['device','FPGA 器件 / 工具版本','text'],['lut','LUT 占用','number'],['ff','FF 占用','number'],['bram','BRAM 块数','number'],['dsp','DSP 占用','number'],['clock','目标时钟 / MHz','number'],['wns','WNS / ns（可为负）','number'],['latency','测量延迟 / 拍','number'],['throughput','测量吞吐率 / Mpix/s','number'],['timing','时序结论 / 约束 / 报告位置','textarea'],['issues','问题、排查过程与解决结果','textarea'],['conclusion','实验结论与下一步','textarea']];
function experiments(){return chapterHead('experiments','每次实验都留下输入、条件、结果与证据。缺少实测值时留空，不用估计值替代。')+`<div class="stack">${panel('实验记录',`<div class="panel-body">${state.experiments.length?state.experiments.map(experimentCard).join(''):'<div class="empty"><h3>还没有实验记录</h3>可以先在算法对比中运行演示并保存，也可以录入自己的仿真或上板结果。<br><a href="#algorithms" style="display:inline-block;margin-top:18px">开始第一组算法对比 →</a></div>'}</div>`,`<button class="primary small" data-action="new-experiment">＋ 记录实验</button>`)}<div class="two-col">${panel('评价指标与使用边界',`<div class="panel-body"><h3>PSNR：与参考图的逐像素误差</h3><div class="formula">MSE = Σ(I − K)² / N<br>PSNR = 10 log₁₀(255² / MSE)</div><p class="muted">MSE = 0 时 PSNR 为 ∞。只有配准且同尺寸的干净参考图才能用于这个比较。真实无参考图数据可记录残留坏点、边缘和任务表现，不编造 PSNR。</p><h3 class="gap">SSIM：亮度、对比度与结构</h3><div class="formula">SSIM = ((2μₓμᵧ+C₁)(2σₓᵧ+C₂))<br> / ((μₓ²+μᵧ²+C₁)(σₓ²+σᵧ²+C₂))</div><p class="muted">结果取决于窗口、权重、边界、常量与数据范围。比较前确保口径一致，并补充小目标保留情况。</p><a href="https://www.ece.uwaterloo.ca/~z70wang/research/ssim/" target="_blank" rel="noopener" class="small">查看 SSIM 作者资料与实现 ↗</a></div>`)}${panel('实验完整性检查',`<div class="panel-body">${checklist(['exp-1','exp-2','exp-3','exp-4','exp-5','exp-6'],['保存输入、参考图与算法版本','记录噪声模型、密度、随机种子与位深映射','比较相同输入、边界策略和指标实现','测试无噪声、低/高密度、全黑/全白、窄线和小目标','验证复位、输入停顿、首末行、valid 对齐与输出数量','保存综合报告、时钟约束和布局布线后时序结果'])}<div class="callout">WNS ≥ 0 仅说明对应分析条件下最差建立时间裕量非负；仍需检查所有时钟、保持时间、未约束路径及其他时序检查。</div></div>`)}</div></div>`;}
function experimentCard(e){return `<article class="record-card"><div class="row spread"><span class="chip">${esc(e.kind||'手动实验')}</span><span class="small muted">${esc(e.date||'')}</span></div><h3 style="margin-top:12px">${esc(e.title)}</h3><p>${esc(e.algorithm||'')} · ${esc(e.dataset||'数据源待补充')}</p><div class="chips"><span class="chip">PSNR ${esc(e.psnr||'—')} dB</span><span class="chip">SSIM ${esc(e.ssim||'—')}</span><span class="chip">LUT ${esc(e.lut||'待实测')}</span><span class="chip">WNS ${esc(e.wns||'待实测')} ns</span></div><details><summary>查看完整参数与结果</summary><dl>${expFields.filter(([k])=>!['title','algorithm','dataset'].includes(k)).map(([k,label])=>`<dt>${label}</dt><dd>${esc(e[k]||'未记录')}</dd>`).join('')}</dl></details><div class="actions"><button data-action="edit-experiment" data-id="${e.id}">补充 / 编辑</button>${e.referencePixels?`<button data-action="replay-experiment" data-id="${e.id}">复现此实验</button>`:''}<button class="danger" data-action="delete" data-kind="experiments" data-id="${e.id}">删除</button></div></article>`;}
const categories=['论文','算法','Verilog','FPGA','实验数据','待验证想法'];
function library(){return pageHead('RESEARCH LIBRARY / 我的工作区','研究资料库','把论文、实现、实验和问题放在同一处。所有记录可导出备份。',`<button class="primary" data-action="new-note">＋ 新建笔记</button>`)+`<div class="row spread filters"><input id="librarySearch" class="search" aria-label="搜索所有研究资料" placeholder="搜索标题、内容、参数…" value="${esc(libraryQuery)}"><div class="row"><button data-action="export">导出备份</button><button data-action="import">导入备份</button></div></div><div class="tabs">${['全部',...categories].map(c=>`<button data-action="category" data-category="${c}" class="${libraryCategory===c?'active':''}">${c}</button>`).join('')}</div><div class="two-col"><div id="libraryResults"></div><div class="stack">${reviewPanel()}${panel('自定义任务',`<div class="panel-body">${state.tasks.length?taskMarkup(state.tasks):'<p class="muted">将下一步行动写成一个可以完成的小任务。</p>'}<button class="small gap" data-action="new-task">＋ 添加任务</button></div>`)}${progressPanel()}</div></div>`;}
function renderLibrary(){if(!$('#libraryResults'))return;const list=[...state.papers.map(r=>({...r,category:'论文',recordKind:'paper'})),...state.experiments.map(r=>({...r,category:'实验数据',recordKind:'experiment'})),...state.notes.map(r=>({...r,recordKind:'note'}))].filter(r=>(libraryCategory==='全部'||r.category===libraryCategory)&&Object.values(r).join(' ').toLowerCase().includes(libraryQuery.toLowerCase()));$('#libraryResults').innerHTML=list.length?list.map(r=>r.recordKind==='paper'?paperCard(r):r.recordKind==='experiment'?experimentCard(r):noteCard(r)).join(''):'<div class="empty"><h3>这里还没有匹配的资料</h3>新建一条笔记，或换一个分类和关键词。</div>';}
function noteCard(n){return `<article class="record-card"><div class="row spread"><span class="chip">${esc(n.category)}</span><span class="small muted">${esc(n.status||'待整理')}</span></div><h3 style="margin-top:12px">${esc(n.title)}</h3><p>${esc(n.body||'暂无内容')}</p>${n.reviewDate?`<p>计划复习：${esc(n.reviewDate)}</p>`:''}<div class="actions"><button data-action="edit-note" data-id="${n.id}">编辑</button><button data-action="review-note" data-id="${n.id}">复习完成</button><button class="danger" data-action="delete" data-kind="notes" data-id="${n.id}">删除</button></div></article>`;}
function reviewPanel(){const today=new Date().toLocaleDateString('sv-SE');const due=[...state.papers.map(r=>({...r,kind:'paper'})),...state.notes.map(r=>({...r,kind:'note'}))].filter(r=>r.reviewDate&&r.reviewDate<=today);return panel('待复习列表',`<div class="panel-body">${due.length?due.map(r=>`<div class="task"><div><strong>${esc(r.title)}</strong><p>${esc(r.reviewDate)} · ${r.kind==='paper'?'论文':'笔记'}</p><button class="text-button small" data-action="edit-${r.kind}" data-id="${r.id}">打开记录 →</button></div></div>`).join(''):'<p class="muted">暂无到期内容。在论文或笔记中设置复习日期，到期后会显示在这里。</p>'}</div>`,`<span class="stat-tag">${due.length}</span>`);}
function inputField([key,label,type,required],value=''){let attrs=type==='number'?' step="any"':'';if(['lut','ff','dsp','latency'].includes(key))attrs=' min="0" step="1"';if(['bram','throughput'].includes(key))attrs=' min="0" step="any"';if(key==='clock')attrs=' min="0.001" step="any"';if(key==='ssim')attrs=' min="-1" max="1" step="any"';return `<label class="field ${required?'required':''} ${type==='textarea'?'full':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${key}" maxlength="100000" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''}${attrs} ${type==='text'?'maxlength="1000"':''}>`}</label>`;}
function openForm(kind,record={}){const titles={paper:'论文精读笔记',note:'研究笔记',experiment:'实验记录',task:'下一步任务'};let fields=kind==='paper'?paperFields:kind==='experiment'?expFields:kind==='task'?[['title','下一步要做什么','text',true],['detail','完成条件 / 说明','textarea']]:[['title','笔记标题','text',true],['body','正文 / 研究问题 / 想法 / 排查过程','textarea'],['reviewDate','计划复习日期','date']];let additional='';if(kind==='paper')additional=`<label class="field"><span>阅读状态</span><select name="status">${['待阅读','精读中','待复现','已整理'].map(s=>`<option ${record.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`;if(kind==='note')additional=`<label class="field"><span>资料分类</span><select name="category">${categories.map(s=>`<option ${record.category===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field"><span>记录状态</span><select name="status">${['待整理','待验证','验证中','已验证','已否定'].map(s=>`<option ${record.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`;if(kind==='experiment')additional=`<label class="field"><span>结果来源</span><select name="kind">${['手动实验','软件仿真','FPGA 综合','FPGA 上板','浏览器教学实验'].map(s=>`<option ${record.kind===s?'selected':''}>${s}</option>`).join('')}</select></label>`;$('#editor').innerHTML=`<div class="dialog-head"><h2>${record.id?'编辑':'新建'}${titles[kind]}</h2><button class="text-button" data-action="close-dialog" aria-label="关闭">✕</button></div><form id="recordForm" class="dialog-body"><p class="small muted" style="margin-bottom:20px">${kind==='paper'?'先写标题即可保存，其余内容可在阅读过程中逐步补全。所有解释请回到原文核对。':kind==='experiment'?'只填已获得的结果。没有参考图或尚未上板的项目请留空。':'把内容拆成具体、可复查的记录，稍后可以继续编辑。'}</p><div class="split-fields">${fields.map(f=>inputField(f,record[f[0]]??'')).join('')}${additional}</div>${kind==='paper'?'<button type="button" class="gap" data-action="reading-prompts">生成待核对的精读问题</button><p class="muted small">依据已填内容生成阅读提示，不代替原文分析或自动翻译。</p>':''}<div class="dialog-footer"><button type="button" data-action="close-dialog">取消</button><button type="submit" class="primary">保存记录</button></div></form>`;$('#editor').showModal();$('#recordForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(kind==='experiment'&&data.psnr&&data.psnr!=='Infinity'&&!Number.isFinite(Number(data.psnr))){toast('PSNR 请填写数值或 Infinity');return;}if(!data.title?.trim()){toast('请填写有效标题');return;}if(kind==='experiment'&&!data.algorithm?.trim()){toast('请填写算法或版本');return;}const key={paper:'papers',note:'notes',experiment:'experiments',task:'tasks'}[kind];const obj={...record,...data,title:data.title.trim(),id:record.id||uid(),date:record.date||new Date().toLocaleDateString('sv-SE')};const i=state[key].findIndex(x=>x.id===obj.id);if(i>=0)state[key][i]=obj;else state[key].unshift(obj);persist();$('#editor').close();if(kind==='paper')selectedPaper=obj.id;render();toast(storageOK?'记录已保存到此浏览器':'记录已暂存内存，请导出备份');};}
function confirmDialog(title,text,onConfirm){$('#editor').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2></div><div class="dialog-body"><p>${esc(text)}</p><div class="dialog-footer"><button data-action="close-dialog">取消</button><button id="confirmAction" class="primary">确认</button></div></div>`;$('#editor').showModal();$('#confirmAction').onclick=()=>{$('#editor').close();onConfirm();};}
function saveDemo(model=demo,result=latest){if(!result)return;const input=Array.from(model.reference).join(',');const e={id:uid(),title:`${methodNames[model.method]} · ${noiseNames[model.type]} ${model.level}${model.type==='salt'?'%':''}`,algorithm:methodNames[model.method],dataset:model.source,params:`尺寸 96×96；8 位；3×3；边界复制；噪声 ${noiseNames[model.type]}；强度 ${model.level}；种子 ${model.seed}；阈值 ${model.threshold}；均值四舍五入；高斯叠加后截断。`,psnr:Number.isFinite(result.m.psnr)?result.m.psnr.toFixed(4):'Infinity',ssim:result.m.ssim.toFixed(6),ssimMethod:'8×8 不重叠均匀分块，使用总体方差；K1=.01，K2=.03，L=255',kind:'浏览器教学实验',date:new Date().toLocaleDateString('sv-SE'),referencePixels:input,noiseType:model.type,noiseLevel:String(model.level),seed:String(model.seed),filterMethod:model.method,threshold:String(model.threshold),conclusion:'教学数据；不是 FPGA 实测。已随记录保存参考像素，可通过 JSON 备份复现。'};state.experiments.unshift(e);persist();toast(storageOK?'实验已保存，可在“实验评估”补充结论和硬件结果':'浏览器存储不可用，实验仅暂存内存，请立即导出备份');}
let currentComparison=[];
function historyMarkup() {
  const groups=state.experiments.filter(r=>r.comparisonText);
  return groups.length?groups.map(r=>`<details class="saved-comparison"><summary>${esc(r.title)}</summary><p>${esc(r.params)}</p><pre>${esc(r.comparisonText)}</pre></details>`).join(''):'<p>还没有对比记录。调好参数后，点上方「保存三种方法的对比数据」。</p>';
}
function updateLab() {
  currentComparison=compareMethods(demo,latest.noisy,methodNames);
  displayComparison(currentComparison,drawCanvas);
  $('#saveComparison').disabled=false;
  $('#saveComparison').textContent='保存三种方法的对比数据';
}
function bindLab() {
  $('#lampPreset').onclick=()=>{
    Object.assign(demo,{reference:lampScene(),source:'合成路灯街景',level:16,method:'median',type:'salt',seed:42,threshold:30});
    render();toast('已载入路灯街景与固定对照参数');
  };
  $('#saveComparison').onclick=()=>{
    const comparisonText=currentComparison.map(r=>r.name+'　MSE '+r.mse.toFixed(2)+'　PSNR '+(Number.isFinite(r.psnr)?r.psnr.toFixed(2):'∞')+' dB　SSIM '+r.ssim.toFixed(4)).join('\n');
    const params=`${demo.source} · 96×96 · ${noiseNames[demo.type]} ${demo.level}${demo.type==='salt'?'%':''} · 种子 ${demo.seed} · 阈值 ${demo.threshold} · 3×3 边界复制`;
    const title=`三法对比 · ${noiseNames[demo.type]} ${demo.level}${demo.type==='salt'?'%':''} · ${new Date().toLocaleTimeString('zh-CN')}`;
    state.experiments.unshift({id:uid(),title,params,comparisonText,conclusion:comparisonText,kind:'浏览器教学实验',algorithm:'均值 / 中值 / 开关中值',dataset:demo.source,date:new Date().toLocaleDateString('sv-SE')});
    persist();$('#labHistory').innerHTML=historyMarkup();$('#labHistory details').open=true;
    $('#saveComparison').disabled=true;$('#saveComparison').textContent=storageOK?'本组数据已保存':'本组数据已暂存内存';
  };
  $('#paperRis').onchange=async e=>{
    const input=e.target, file=input.files[0], message=$('#risMessage');
    if(!file)return;
    try {
      if(file.size>1000000)throw Error('引文文件请小于 1 MB。');
      const papers=readRis(await file.text());
      const key=p=>p.title.trim().toLowerCase();
      const seen=new Set(state.papers.map(key));
      const fresh=papers.filter(p=>{if(seen.has(key(p)))return false;seen.add(key(p));return true;});
      const next={...state,papers:[...fresh.map(p=>({...p,id:uid()})),...state.papers]};
      validateState(next);
      state=next;persist();message.textContent=`已导入 ${fresh.length} 篇，略过 ${papers.length-fresh.length} 篇重复引文。${storageOK?'':'记录仅暂存内存，请导出备份。'}`;
    }catch(error){message.textContent=error.message||'未能读取引文文件。';}finally{input.value='';}
  };
}
function render(){stopTour();if(timer){clearInterval(timer);timer=null;}page=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'home';document.body.classList.remove('menu-open');renderSidebar();$('#topbar').innerHTML=`<div class="row"><button class="menu-button" data-action="menu" aria-label="打开导航">☰</button><span>工作区 <span style="margin:0 10px;color:#bec6b5">/</span> <span style="color:#49563e">${names[page]}</span></span></div><div class="top-actions"><span class="save-label"><span class="status-dot"></span>${storageOK?'本地自动保存':'仅内存保存'}</span><button data-action="export">导出备份 ↗</button></div>`;const views={home:homePage,lab:()=>labPage(demoPanel(),historyMarkup()),guide:tutorial,knowledge,overview,basics,papers,algorithms,ideas,hardware:hardwarePage,experiments,library};$('#main').innerHTML=(loadError?`<div class="storage-warning">${loadError}</div>`:'')+views[page]();document.title=names[page]+' · 红外去噪研究台';bindDemo();if(page==='home')paintScenes();if(page==='lab')bindLab();if(page==='guide')bindTutorial(saveDemo);if(page==='knowledge')bindKnowledge();if(page==='basics'){updateWindow();$('#flowDetail').textContent=flowDetails[0];}if(page==='papers'){renderTerms();$('#termSearch').oninput=e=>renderTerms(e.target.value);}if(page==='hardware'){updateHardware();$$('[id^="hw"]').filter(e=>e.tagName==='INPUT').forEach(e=>e.oninput=updateHardware);}if(page==='library'){renderLibrary();$('#librarySearch').oninput=e=>{libraryQuery=e.target.value;renderLibrary();};}}
document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){location.hash=go.dataset.go;return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='menu'){document.body.classList.toggle('menu-open');return;}if(a==='export')return exportAll();if(a==='import')return $('#importFile').click();if(a==='close-dialog')return $('#editor').close();if(a==='new-paper')return openForm('paper');if(a==='new-note')return openForm('note',{category:libraryCategory!=='全部'?libraryCategory:'算法'});if(a==='new-experiment')return openForm('experiment');if(a==='new-task')return openForm('task');if(a==='new-idea'||a==='idea-template')return openForm('note',{category:'待验证想法',status:'待验证',body:a==='idea-template'?'问题：\n改变：\n假设：\n基线：\n指标：\n代价：\n反例：':''});if(a==='verilog-note')return openForm('note',{category:'Verilog',title:'3×3 中值滤波接口与实现',body:'接口约定：\n位宽与符号：\n窗口生成：\n流水线级数：\nvalid 对齐：\n仿真结果：'});if(a==='hardware-note')return openForm('note',{category:'FPGA',title:'问题排查记录',body:'现象：\n复现输入与条件：\n定位假设：\n检查过程：\n修复方式：\n复测结果：'});if(a.startsWith('edit-')){const kind=a.slice(5),key={paper:'papers',note:'notes',experiment:'experiments'}[kind];return openForm(kind,state[key].find(r=>r.id===id));}if(a==='read-paper'){selectedPaper=id;if(page==='papers'){render();$('#main').scrollIntoView();}else location.hash='papers';return;}if(a==='sample-paper')return openForm('paper',{title:'Image Quality Assessment: From Error Visibility to Structural Similarity',url:'https://www.ece.uwaterloo.ca/~z70wang/publications/ssim.html',keywords:'SSIM; image quality assessment; structural similarity',status:'待阅读',questions:'待核对：SSIM 如何定义？其窗口、常量与图像范围是什么？与本研究的分块教学实现有何区别？'});if(a==='delete'){const key=b.dataset.kind;return confirmDialog('删除这条记录？','此操作删除当前浏览器中的这一条记录。需要保留时，请先导出备份。',()=>{state[key]=state[key].filter(r=>r.id!==id);persist();render();toast('记录已删除');});}if(a==='delete-task'){state.tasks=state.tasks.filter(r=>r.id!==id);persist();render();return;}if(a==='review-paper'||a==='review-note'){const key=a==='review-paper'?'papers':'notes',r=state[key].find(r=>r.id===id);const d=new Date();d.setDate(d.getDate()+7);r.reviewDate=d.toLocaleDateString('sv-SE');r.lastReviewed=new Date().toLocaleDateString('sv-SE');persist();render();toast('已标记复习完成，下次安排在 7 天后');return;}if(a==='chapter'){state.chapters=state.chapters.includes(id)?state.chapters.filter(x=>x!==id):[...state.chapters,id];persist();render();return;}if(a==='category'){libraryCategory=b.dataset.category;render();return;}if(a==='save-demo')return saveDemo();if(a==='reset-image'){demo.reference=phantom();demo.source='合成灰度测试图';updateDemo();return;}if(a==='download-image'){const anchor=document.createElement('a');anchor.download='去噪结果.png';anchor.href=$('#outCanvas').toDataURL();anchor.click();return;}if(a==='flow'){$$('#pipeline button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#flowDetail').textContent=flowDetails[Number(b.dataset.index)];return;}if(a.startsWith('window-')){if(a==='window-play'){if(timer){clearInterval(timer);timer=null;b.textContent='自动播放';}else{if(windowIndex===24)windowIndex=0;b.textContent='暂停';timer=setInterval(()=>{windowIndex++;if(windowIndex>=24){windowIndex=24;clearInterval(timer);timer=null;$('#windowPlay').textContent='自动播放';}updateWindow();},650);}return;}if(timer){clearInterval(timer);timer=null;$('#windowPlay').textContent='自动播放';}windowIndex=a==='window-reset'?0:Math.max(0,Math.min(24,windowIndex+(a==='window-next'?1:-1)));updateWindow();}});
document.addEventListener('change',e=>{const key=e.target.dataset.check||e.target.dataset.task;if(!key)return;state.checks=e.target.checked?[...new Set([...state.checks,key])]:state.checks.filter(x=>x!==key);const task=state.tasks.find(t=>t.id===key);if(task)task.done=e.target.checked;persist();});
$('#importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('备份超过 10 MB');const incoming=validateState(JSON.parse(await file.text()));confirmDialog('合并导入备份？','导入会添加新记录，并用备份内容更新相同编号的记录。当前其他记录保留。',()=>{for(const key of ['papers','notes','experiments','tasks']){const records=new Map(state[key].map(r=>[r.id,r]));incoming[key].forEach(r=>records.set(r.id,r));state[key]=[...records.values()];}state.chapters=[...new Set([...state.chapters,...incoming.chapters])].filter(x=>chapters.some(c=>c[0]===x));state.checks=[...new Set([...state.checks,...incoming.checks])];persist();render();toast(storageOK?'备份已合并导入':'备份已合并到内存，浏览器存储不可用，请导出保存');});}catch(err){toast('导入失败：'+err.message);}};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();

document.addEventListener('click',e=>{
  const button=e.target.closest('[data-action]');if(!button)return;
  if(button.dataset.action==='replay-experiment'){
    const record=state.experiments.find(r=>r.id===button.dataset.id);
    try{
      const values=record.referencePixels.split(',').map(Number);
      if(values.length!==9216||values.some(v=>!Number.isInteger(v)||v<0||v>255))throw Error('参考像素不完整');
      const level=Number(record.noiseLevel),seed=Number(record.seed),threshold=Number(record.threshold);
      if(!noiseNames[record.noiseType]||!methodNames[record.filterMethod]||!Number.isFinite(level)||level<0||level>90||!Number.isInteger(seed)||seed<0||seed>4294967295||!Number.isInteger(threshold)||threshold<0||threshold>255)throw Error('实验参数不完整');
      demo={...demo,reference:Uint8Array.from(values),source:record.dataset,type:record.noiseType,level,seed,method:record.filterMethod,threshold};
      if(page==='algorithms')render();else location.hash='algorithms';
      toast('已恢复保存的参考像素与实验参数');
    }catch(error){toast('无法复现：'+error.message);}
  }
  if(button.dataset.action==='reading-prompts'){
    const f=$('#recordForm'),field=n=>f.elements.namedItem(n).value.trim();
    const prompts=[`研究问题：${field('title')||'这篇论文'}具体解决什么问题？适用哪些噪声和输入？`, `核心方法：${field('method')?'逐项核对已记录的方法':'找出检测、滤波和输出步骤'}，为什么这样设计？`, `数据与对照：${field('dataset')||'数据来源待确认'}是否有干净参考图？不同方法的条件是否一致？`, '证据：提升是否跨越多个噪声密度和图像成立？有没有小目标或真实坏点反例？', '改进：哪些操作可用比较器、有限位宽加法器和行缓存实现？代价是什么？'];
    f.elements.namedItem('questions').value=[field('questions'),prompts.join('\n')].filter(Boolean).join('\n\n');
    const paragraph=field('paragraph').toLowerCase();
    const terms=glossary.filter(([term])=>paragraph.includes(term.toLowerCase())).map(([term,cn,meaning])=>`${term} / ${cn}：${meaning}`);
    if(terms.length)f.elements.namedItem('terms').value=[field('terms'),terms.join('\n')].filter(Boolean).join('\n');
    toast('已添加精读问题；匹配到的段落术语已补入术语栏，保存后保留');
  }
});
